'use strict';
let reconReport=null,reconPage=0,reconSelected=new Set();
const reconAction=(message,fn)=>run(message,fn,'recon-notice');
function reconSources(rows){for(const role of ['reference','delivery']){const el=$('recon-'+role),previous=el.value;el.innerHTML='<option value="">Choose a saved CSV</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)} · ${r.id.slice(0,8)}</option>`).join('');if(rows.some(r=>r.id===previous))el.value=previous;}}
async function reconHistory(){const rows=await api('/api/reconciliations');$('recon-history').innerHTML='<option value="">Choose a saved comparison</option>'+rows.map(r=>`<option value="${r.id}">${esc(r.scope)} · ${esc(r.stage)} · ${r.matched?'matches':'review'} · ${r.id.slice(0,8)}</option>`).join('');if(reconReport)$('recon-history').value=reconReport.id;}
function reconOpen(r){reconReport=r;reconPage=0;reconSelected=new Set();reconRender();}
function reconRender(){
 const r=reconReport;if(!r)return;const start=reconPage*50,shown=r.issues.slice(start,start+50),canRepair=r.stage==='comparison'&&!r.blockers.length&&r.issues.length;
 $('recon-report').innerHTML=`<h3>${r.stage==='candidate'?'Repair candidate':'Snapshot comparison'} · ${r.matched?'Matches nominated reference':'Needs review'}</h3><p>${esc(r.names.reference)} ↔ ${esc(r.names.delivery)}</p><div class="review-note">${esc(r.contract.scope)} · reference ${esc(r.contract.reference_date)} / delivery ${esc(r.contract.delivery_date)} · assessed ${esc(r.contract.as_of)}</div><p>${r.counts.reference_rows} reference rows · ${r.counts.delivery_rows} delivered rows · ${r.counts.matched_keys} matching identities · ${r.issues.length} discrepant identities</p>
 ${r.blockers.length?`<div class="issues"><strong>Candidate repairs blocked</strong>${r.blockers.map(b=>`<p>${esc(b)}</p>`).join('')}</div>${r.invalid.reference.length||r.invalid.delivery.length?`<details><summary>Invalid identity records</summary><pre>${esc(JSON.stringify(r.invalid,null,2))}</pre></details>`:""}`:''}
 <details><summary>Contract, reference authority and source fingerprints</summary><pre>${esc(JSON.stringify({engine:r.engine,contract:r.contract,sources:r.sources},null,2))}</pre></details>
 <p>${r.issues.length?`Showing ${start+1}–${Math.min(start+50,r.issues.length)} of ${r.issues.length} discrepancies. Record 1 is the header.`:r.blockers.length?'No comparable identity differences; the blockers above still apply.':'Every identity and field agrees with the reference.'}</p>
 ${shown.map(i=>`<div class="replay-issue">${canRepair?`<label><input type="checkbox" data-recon-issue="${i.id}" ${reconSelected.has(i.id)?'checked':''}> ${i.kind==='unexpected'?'Remove ALL delivered rows for':'Replace ALL delivered rows for'} ${esc(JSON.stringify(i.key))}${i.kind==='unexpected'?' · absent from reference':' · use exact reference row'}</label>`:''}<details><summary>${esc(i.kind)} · ${esc(JSON.stringify(i.key))} · ${i.delivery.length} delivered / ${i.reference.length} reference</summary><p>Changed fields: ${esc(i.changed_fields.join(', ')||'See identity counts below')}</p><div class="compare-grid"><div><h4>Reference evidence</h4><pre>${esc(JSON.stringify(i.reference,null,2))}</pre></div><div><h4>Delivery evidence</h4><pre>${esc(JSON.stringify(i.delivery,null,2))}</pre></div></div></details></div>`).join('')}
 <div class="detail-actions">${reconPage?'<button id="recon-prev">Previous 50</button>':''}${start+50<r.issues.length?'<button id="recon-next">Next 50</button>':''}</div>
 ${canRepair?'<button id="recon-select">Select discrepancies on this page</button> <button id="recon-clear">Clear selection</button><p id="recon-selection"></p><label for="recon-note">Why are these replacements or removals justified?</label><textarea id="recon-note" maxlength="1000"></textarea><button id="recon-repair" class="primary">Build isolated candidate</button>':''}
 ${r.parent?`<p>Candidate only; no publication occurred. Review note: ${esc(r.note)}</p><button id="recon-parent">Reopen original comparison</button><details><summary>Transformation log</summary><pre>${esc(JSON.stringify(r.changes,null,2))}</pre></details>`:''}
 <p><a class="button" href="/api/reconciliation-bundle/${r.id}" download>Download full evidence bundle</a> ${r.stage==='candidate'?`<a class="button" href="/api/dataset-csv/${r.sources.delivery}" download>Download candidate CSV</a>`:''}</p><p class="small">${esc(r.limitation)} CSV downloads prefix formula-like cells for spreadsheet safety; JSON evidence preserves exact original text.</p>`;
 const update=()=>{if($('recon-selection'))$('recon-selection').textContent=reconSelected.size+' discrepancies selected across pages.';};
 $('recon-report').querySelectorAll('[data-recon-issue]').forEach(c=>c.onchange=()=>{if(c.checked)reconSelected.add(c.dataset.reconIssue);else reconSelected.delete(c.dataset.reconIssue);update();});
 // Preserve an in-progress rationale when moving between result pages.
 function page(delta){const note=$('recon-note')?.value;reconPage+=delta;reconRender();if($('recon-note'))$('recon-note').value=note||'';}
 if($('recon-prev'))$('recon-prev').onclick=()=>page(-1);
 if($('recon-next'))$('recon-next').onclick=()=>page(1);
 if($('recon-select'))$('recon-select').onclick=()=>{$('recon-report').querySelectorAll('[data-recon-issue]').forEach(c=>{c.checked=true;reconSelected.add(c.dataset.reconIssue);});update();};
 if($('recon-clear'))$('recon-clear').onclick=()=>{reconSelected.clear();$('recon-report').querySelectorAll('[data-recon-issue]').forEach(c=>c.checked=false);update();};
 if($('recon-repair'))$('recon-repair').onclick=()=>reconAction('Building and rechecking a separate candidate…',async()=>{const result=await api('/api/reconciliation-repair',{run_id:r.id,issue_ids:[...reconSelected],note:$('recon-note').value});reconOpen(result);await reconHistory();await refreshDatasets();notice(result.matched?'Candidate matches the nominated reference. No original changed or publication occurred.':'Candidate saved; unresolved discrepancies remain.');});
 if($('recon-parent'))$('recon-parent').onclick=()=>reconAction('Opening original comparison…',async()=>{reconOpen(await api('/api/reconciliation/'+r.parent));await reconHistory();notice('Original comparison reopened.');});update();
}
$('recon-load-keys').onclick=()=>reconAction('Reading reference columns…',async()=>{if(!$('recon-reference').value)throw Error('Choose a reference CSV.');const d=await api('/api/dataset/'+$('recon-reference').value);$('recon-keys').innerHTML=d.report.columns.map(c=>`<label><input type="checkbox" name="recon-key" value="${esc(c.name)}"> ${esc(c.name)}</label>`).join('');notice('Select one or more columns that together identify a unique record.');});
$('recon-reference').onchange=()=>{$('recon-keys').innerHTML='';};
for(const role of ['reference','delivery'])$('recon-save-'+role).onclick=()=>reconAction('Saving unchanged CSV…',async()=>{const f=$('recon-file-'+role).files[0];if(!f)throw Error('Choose a CSV file.');if(f.size>2000000)throw Error('CSV exceeds 2 MB.');const source=await api('/api/dataset-save',{name:f.name,content:new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer())});await refreshDatasets();$('recon-'+role).value=source.id;if(role==='reference')$('recon-keys').innerHTML='';notice('CSV saved unchanged. Set its snapshot contract below.');});
$('recon-compare').onclick=()=>reconAction('Comparing the declared snapshots…',async()=>{const input={reference_id:$('recon-reference').value,delivery_id:$('recon-delivery').value,keys:Array.from(document.querySelectorAll('[name="recon-key"]:checked'),c=>c.value),authority:$('recon-authority').value,scope:$('recon-scope').value,reference_date:$('recon-reference-date').value,delivery_date:$('recon-delivery-date').value,as_of:$('recon-as-of').value,max_age_days:Number($('recon-age').value),confirmed:$('recon-confirm').checked};if(!input.reference_id||!input.delivery_id)throw Error('Choose both CSVs.');if($('recon-age').value==='')throw Error('Declare the maximum snapshot age.');reconOpen(await api('/api/reconciliation-compare',input));await reconHistory();notice('Comparison saved with the declared authority, dates and scope.');});
$('recon-history').onchange=()=>reconAction('Opening saved comparison…',async()=>{if(!$('recon-history').value)return;reconOpen(await api('/api/reconciliation/'+$('recon-history').value));notice('Saved evidence opened unchanged; freshness is relative to its recorded assessment date.');});
document.addEventListener('datasets-updated',e=>reconSources(e.detail));
Promise.all([api('/api/datasets').then(reconSources),reconHistory()]).catch(e=>{$('recon-notice').textContent=e.message;});
